DO $test$
DECLARE r jsonb; before_t jsonb; after_t jsonb; rejected boolean; n text; before_a jsonb; before_p jsonb; expected_page integer; calls bigint;
BEGIN
 PERFORM pg_advisory_xact_lock(2026083000261022);
 IF 1197+50<>1247 OR NOT (1247>1197) THEN RAISE EXCEPTION 'FINITE_BOUNDARY_ARITHMETIC_FAILED';END IF;
 IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_task WHERE status='LEASED') THEN RAISE EXCEPTION 'FIXTURE_ACTIVE_ATTEMPT_WAIT';END IF;
 SELECT count(*)+1 INTO expected_page FROM population_top3000_202608_202609_v1.ctx02_census_page_v1 WHERE partition_key='ctx02-census-v1:0869cb2de1b0fe2ad0789fd4498df455de76ad92aa32805c36417a4cf87bb5cd';
